-- Modify "security_audit" table
ALTER TABLE "security_audit" ADD CONSTRAINT "security_audit_change" CHECK ((char_length((channel)::text) <= 16) AND (char_length((mutation_id)::text) <= 64) AND (char_length((before_status)::text) <= 16) AND (char_length((after_status)::text) <= 16) AND (char_length((before_roles)::text) <= 200) AND (char_length((after_roles)::text) <= 200)), ADD COLUMN "channel" character varying NOT NULL DEFAULT '', ADD COLUMN "actor_user_id" uuid NULL, ADD COLUMN "mutation_id" character varying NOT NULL DEFAULT '', ADD COLUMN "before_status" character varying NOT NULL DEFAULT '', ADD COLUMN "after_status" character varying NOT NULL DEFAULT '', ADD COLUMN "before_roles" character varying NOT NULL DEFAULT '', ADD COLUMN "after_roles" character varying NOT NULL DEFAULT '';
-- Create "admin_mutations" table
CREATE TABLE "admin_mutations" ("id" uuid NOT NULL, "operator_id" uuid NOT NULL, "mutation_id" character varying NOT NULL, "action" character varying NOT NULL, "target_id" uuid NOT NULL, "request_hash" bytea NOT NULL, "changed" boolean NOT NULL, "status" character varying NOT NULL, "roles" character varying NOT NULL DEFAULT '', "auth_version" bigint NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "admin_mutations_action" CHECK ((char_length((action)::text) >= 1) AND (char_length((action)::text) <= 64)), CONSTRAINT "admin_mutations_expiry" CHECK (expires_at > created_at), CONSTRAINT "admin_mutations_hash" CHECK (octet_length(request_hash) = 32), CONSTRAINT "admin_mutations_mutation" CHECK ((char_length((mutation_id)::text) >= 1) AND (char_length((mutation_id)::text) <= 64)), CONSTRAINT "admin_mutations_roles" CHECK (char_length((roles)::text) <= 200), CONSTRAINT "admin_mutations_status" CHECK ((status)::text = ANY ((ARRAY['active'::character varying, 'disabled'::character varying, 'deleting'::character varying])::text[])), CONSTRAINT "admin_mutations_version" CHECK (auth_version >= 1));
-- Create index "adminmutation_expires_at" to table: "admin_mutations"
CREATE INDEX "adminmutation_expires_at" ON "admin_mutations" ("expires_at");
-- Create index "adminmutation_operator_id_mutation_id" to table: "admin_mutations"
CREATE UNIQUE INDEX "adminmutation_operator_id_mutation_id" ON "admin_mutations" ("operator_id", "mutation_id");
